CREATE TABLE IF NOT EXISTS users (id VARCHAR(32) PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(254) UNIQUE NOT NULL,password TEXT NOT NULL,role VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS services (id VARCHAR(32) PRIMARY KEY,kind VARCHAR(20) NOT NULL,name TEXT NOT NULL,origin TEXT NOT NULL,destination TEXT NOT NULL,price INTEGER NOT NULL CHECK(price>0),capacity INTEGER NOT NULL CHECK(capacity>0),active INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bookings (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL REFERENCES users(id),service_id VARCHAR(32) NOT NULL REFERENCES services(id),travel_date VARCHAR(10) NOT NULL,quantity INTEGER NOT NULL CHECK(quantity>0),passenger TEXT NOT NULL,total INTEGER NOT NULL,status VARCHAR(20) NOT NULL);
CREATE TABLE IF NOT EXISTS payments (id VARCHAR(32) PRIMARY KEY,booking_id VARCHAR(32) UNIQUE NOT NULL REFERENCES bookings(id),amount INTEGER NOT NULL,status VARCHAR(30) NOT NULL);
CREATE INDEX IF NOT EXISTS booking_inventory ON bookings(service_id,travel_date,status);

CREATE TABLE IF NOT EXISTS wishlist (user_id VARCHAR(32) NOT NULL REFERENCES users(id),service_id VARCHAR(32) NOT NULL REFERENCES services(id),PRIMARY KEY(user_id,service_id));

CREATE TABLE IF NOT EXISTS saved_destinations (user_id VARCHAR(32) NOT NULL REFERENCES users(id), destination VARCHAR(40) NOT NULL, PRIMARY KEY(user_id,destination));
CREATE TABLE IF NOT EXISTS live_quotes (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL REFERENCES users(id),payload TEXT NOT NULL,expires BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS live_trips (id VARCHAR(32) PRIMARY KEY,user_id VARCHAR(32) NOT NULL REFERENCES users(id),payload TEXT NOT NULL,total INTEGER NOT NULL,status VARCHAR(30) NOT NULL);
